from taf.config.testline import NB


class NBAttrs(object):
    def __init__(self, nb_objects):
        self.nb_objects = nb_objects

    def has_nb(self):
        if self.nb_objects is not None:
            return len(self.nb_objects) > 0
        return False

    def get_nb_objects(self):
        if self.nb_objects is None:
            raise AttributeError('No nb in testline object.')
        return [nb for nb in self.nb_objects if isinstance(nb, NB)]
